import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CfmV7b-z.js";const p=JSON.parse('{"title":"CachierFiles","description":"","frontmatter":{"title":"CachierFiles"},"headers":[],"relativePath":"api/lib/cachier-files.md","filePath":"api/lib/cachier-files.md"}'),o={name:"api/lib/cachier-files.md"};function c(s,e,d,l,n,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="cachierfiles" tabindex="-1">CachierFiles <a class="header-anchor" href="#cachierfiles" aria-label="Permalink to &quot;CachierFiles&quot;">​</a></h1><h2 id="new-cachierfiles" tabindex="-1"><code>new CachierFiles([opts], [readFormatter], [writeFormatter], [log])</code> <a class="header-anchor" href="#new-cachierfiles" aria-label="Permalink to &quot;`new CachierFiles([opts], [readFormatter], [writeFormatter], [log])` {#new-cachierfiles}&quot;">​</a></h2><p>Node.js [file]<a href="https://nodejs.org/api/fs.html" target="_blank" rel="noreferrer">https://nodejs.org/api/fs.html</a> persistence manager that uses the file system for improved debugging/caching capabilities</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>[opts]</td><td><code>TemplateFileOpts</code></td><td>The <a href="./template-file-options#new-templatefileopts">TemplateFileOpts</a></td></tr><tr><td>[readFormatter]</td><td><code>function</code></td><td>The <code>function(string, readFormatOptions)</code> that will return a formatted string for <strong>reading</strong><br>data using the <code>options.readFormatOptions</code> from <a href="./template-options#new-templateopts">TemplateOpts</a> as the formatting options. Typically reads are for <strong>HTML</strong><br><em>minification</em> and/or <em>beautifying</em>. <strong>NOTE: Use with caution as syntax errors may result depending on the formatter used and the<br>complexity of the data being formatted!</strong></td></tr><tr><td>[writeFormatter]</td><td><code>function</code></td><td>The <code>function(string, writeFormatOptions)</code> that will return a formatted string for <strong>writting</strong><br>data using the <code>options.writeFormatOptions</code> from <a href="./template-options#new-templateopts">TemplateOpts</a> as the formatting options. Typically reads are for <strong>JS</strong><br><em>minification</em> and/or <em>beautifying</em>. <strong>NOTE: Use with caution as syntax errors may result depending on the formatter used and the<br>complexity of the data being formatted!</strong></td></tr><tr><td>[log]</td><td><code>Object</code></td><td>The log for handling logging output</td></tr><tr><td>[log.debug]</td><td><code>function</code></td><td>A function that will accept <strong>debug</strong> level logging messages (i.e. <code>debug(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.info]</td><td><code>function</code></td><td>A function that will accept <strong>info</strong> level logging messages (i.e. <code>info(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.warn]</td><td><code>function</code></td><td>A function that will accept <strong>warning</strong> level logging messages (i.e. <code>warn(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.error]</td><td><code>function</code></td><td>A function that will accept <strong>error</strong> level logging messages (i.e. <code>error(&#39;some message to log&#39;)</code>)</td></tr></tbody></table><h3 id="cachierfiles-register" tabindex="-1"><code>cachierFiles.register([read], [data], [read], [write])</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachierfiles-register" aria-label="Permalink to &quot;`cachierFiles.register([read], [data], [read], [write])` ⇒ `Object` {#cachierfiles-register}&quot;">​</a></h3><p>Registers and caches the tempalte, one or more partials and/or context within the internal file system. Also creates any missing directories/sub-directories within the <a href="./template-file-options#new-templatefileopts">TemplateFileOpts</a> <code>outputPath</code> directory from <code>partialsPath</code> sub-directories.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>[read]</td><td><code>Boolean</code></td><td>When <code>true</code>, an attempt will be made to also <em>read</em> any partials using option parameter</td></tr><tr><td>[data]</td><td><code>Array.&lt;Object&gt;</code></td><td>The template, partials and/or context to register.</td></tr><tr><td>partials[].name</td><td><code>String</code></td><td>The name that uniquely identifies the template, partial or context</td></tr><tr><td>[partials[].content]</td><td><code>String</code></td><td>The raw content that will be registered. Omit when <code>read === true</code> to read content from cache.</td></tr><tr><td>[partials[].params]</td><td><code>URLSearchParams</code></td><td>The <code>URLSearchParams</code> that will be passed during the content <code>read</code><br>(<strong>ignored when <code>content</code> is specified</strong>).</td></tr><tr><td>[partials[].extension]</td><td><code>String</code></td><td>Optional override for a file extension designated for a template, partial or context.</td></tr><tr><td>[read]</td><td><code>Boolean</code></td><td>When <code>true</code>, an attempt will be made to also <a href="./cachier#cachier-read">Cachier.read</a> the template, partials and context that<br><strong>do not have</strong> a <code>content</code> property set.</td></tr><tr><td>[write]</td><td><code>Boolean</code></td><td>When <code>true</code>, an attempt will be made to also <a href="./cachier#cachier-write">Cachier.write</a> the template, partials and context that<br><strong>have</strong> a <code>content</code> property set.</td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><p><code>Object</code> — An object that contains the registration results:</p></li><li><p><code>data</code> The object that contains the template, partial fragments and/or context that have been registered</p><ul><li><code>name</code> The name that uniquely identifies the template, partial or context</li><li><code>content</code> The raw content of the template, partial or context</li><li><code>extension</code> The template file extension designation</li><li><code>params</code> The URLSearchParams passed during the <strong>initial</strong> content read</li><li><code>fromRead</code> A flag that indicates that the data was set from a read operation</li><li><code>overrideFromFileRead</code> A flag that indicates if the passed partial content was overridden by content from a file read</li></ul></li><li><p><code>dirs</code> Contains the directories/sub-directories that were created</p></li></ul><h3 id="cachierfiles-compile" tabindex="-1"><code>cachierFiles.compile()</code> <a class="header-anchor" href="#cachierfiles-compile" aria-label="Permalink to &quot;`cachierFiles.compile()` {#cachierfiles-compile}&quot;">​</a></h3><p><strong>Async:</strong> yes</p><h3 id="cachierfiles-read" tabindex="-1"><code>cachierFiles.read()</code> <a class="header-anchor" href="#cachierfiles-read" aria-label="Permalink to &quot;`cachierFiles.read()` {#cachierfiles-read}&quot;">​</a></h3><p><strong>Async:</strong> yes</p><h3 id="cachierfiles-write" tabindex="-1"><code>cachierFiles.write()</code> <a class="header-anchor" href="#cachierfiles-write" aria-label="Permalink to &quot;`cachierFiles.write()` {#cachierfiles-write}&quot;">​</a></h3><p><strong>Async:</strong> yes</p><h3 id="cachierfiles-metadata" tabindex="-1"><code>cachierFiles.metadata</code> <a class="header-anchor" href="#cachierfiles-metadata" aria-label="Permalink to &quot;`cachierFiles.metadata` {#cachierfiles-metadata}&quot;">​</a></h3><h3 id="cachierfiles-stats" tabindex="-1"><code>cachierFiles.stats</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachierfiles-stats" aria-label="Permalink to &quot;`cachierFiles.stats` ⇒ `Object` {#cachierfiles-stats}&quot;">​</a></h3><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — Combined memory-cache and file-watcher statistics.</li></ul><h3 id="cachierfiles-resetstats" tabindex="-1"><code>cachierFiles.resetStats()</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachierfiles-resetstats" aria-label="Permalink to &quot;`cachierFiles.resetStats()` ⇒ `Object` {#cachierfiles-resetstats}&quot;">​</a></h3><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The reset combined statistics.</li></ul><h3 id="cachierfiles-clearmemory" tabindex="-1"><code>cachierFiles.clearMemory()</code> <a class="header-anchor" href="#cachierfiles-clearmemory" aria-label="Permalink to &quot;`cachierFiles.clearMemory()` {#cachierfiles-clearmemory}&quot;">​</a></h3><p>Clears in-memory template content and compiled renderers while preserving watcher and directory state.</p><p><strong>Async:</strong> yes</p><h3 id="cachierfiles-startwatching" tabindex="-1"><code>cachierFiles.startWatching()</code> ⇒ <code>Number</code> <a class="header-anchor" href="#cachierfiles-startwatching" aria-label="Permalink to &quot;`cachierFiles.startWatching()` ⇒ `Number` {#cachierfiles-startwatching}&quot;">​</a></h3><p>Starts native watchers for <code>partialsPath</code> and reconciles the current partial tree.</p><p><strong>Async:</strong> yes</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Number</code> — The number of active directory watchers.</li></ul><h3 id="cachierfiles-reconcilewatching" tabindex="-1"><code>cachierFiles.reconcileWatching()</code> ⇒ <code>Number</code> <a class="header-anchor" href="#cachierfiles-reconcilewatching" aria-label="Permalink to &quot;`cachierFiles.reconcileWatching()` ⇒ `Number` {#cachierfiles-reconcilewatching}&quot;">​</a></h3><p>Reconciles watched files and directories with the current file system.</p><p><strong>Async:</strong> yes</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Number</code> — The number of files discovered during reconciliation.</li></ul><h3 id="cachierfiles-stopwatching" tabindex="-1"><code>cachierFiles.stopWatching()</code> ⇒ <code>Number</code> <a class="header-anchor" href="#cachierfiles-stopwatching" aria-label="Permalink to &quot;`cachierFiles.stopWatching()` ⇒ `Number` {#cachierfiles-stopwatching}&quot;">​</a></h3><p>Stops all compile-time file watchers and pending watcher work.</p><p><strong>Async:</strong> yes</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Number</code> — The number of closed watchers.</li></ul><h3 id="cachierfiles-cleargeneratedfiles" tabindex="-1"><code>cachierFiles.clearGeneratedFiles([all=false])</code> <a class="header-anchor" href="#cachierfiles-cleargeneratedfiles" aria-label="Permalink to &quot;`cachierFiles.clearGeneratedFiles([all=false])` {#cachierfiles-cleargeneratedfiles}&quot;">​</a></h3><p>Clears generated renderer files without clearing in-memory cache entries.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>[all=false]</td><td><code>Boolean</code></td><td>false</td><td><code>true</code> to clear all matching temporary output directories.</td></tr></tbody></table><h3 id="cachierfiles-clear" tabindex="-1"><code>cachierFiles.clear([all=false])</code> <a class="header-anchor" href="#cachierfiles-clear" aria-label="Permalink to &quot;`cachierFiles.clear([all=false])` {#cachierfiles-clear}&quot;">​</a></h3><p>Clears memory, generated files and file watchers.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>[all=false]</td><td><code>Boolean</code></td><td>false</td><td><code>true</code> to clear all temporary directories created over multiple instances.</td></tr></tbody></table><h3 id="cachierfiles-close" tabindex="-1"><code>cachierFiles.close()</code> <a class="header-anchor" href="#cachierfiles-close" aria-label="Permalink to &quot;`cachierFiles.close()` {#cachierfiles-close}&quot;">​</a></h3><p>Stops watchers and releases memory without deleting generated files.</p><p><strong>Async:</strong> yes</p><h3 id="cachierfiles-readwritenames" tabindex="-1"><code>cachierFiles.readWriteNames</code> <a class="header-anchor" href="#cachierfiles-readwritenames" aria-label="Permalink to &quot;`cachierFiles.readWriteNames` {#cachierfiles-readwritenames}&quot;">​</a></h3><h3 id="cachierfiles-operations" tabindex="-1"><code>cachierFiles.operations</code> <a class="header-anchor" href="#cachierfiles-operations" aria-label="Permalink to &quot;`cachierFiles.operations` {#cachierfiles-operations}&quot;">​</a></h3>',58)])])}const f=t(o,[["render",c]]);export{p as __pageData,f as default};
